from typing import Annotated, Any

from fastapi import APIRouter, Depends, Header, Path

from angel.core.deps import CheckoutServiceDep, CurrentUserDep, no_store
from angel.schemas.order import CheckoutOut, CheckoutRequest, OrderOut, ShippingMethodList
from angel.schemas.problem import ProblemDetail

router = APIRouter(prefix="/checkout", tags=["checkout"], dependencies=[Depends(no_store)])

OrderNumber = Annotated[str, Path(min_length=4, max_length=20)]
# Generated by the client, one per checkout attempt (a UUID is fine).
IdempotencyKey = Annotated[
    str,
    Header(
        min_length=8,
        max_length=100,
        pattern=r"^[A-Za-z0-9_\-]+$",
        description="Repeating a request with the same key returns the same order.",
    ),
]
_CHECKOUT_ERRORS: dict[int | str, dict[str, Any]] = {
    401: {"model": ProblemDetail, "description": "Not signed in"},
    404: {"model": ProblemDetail, "description": "Address not found"},
    409: {"model": ProblemDetail, "description": "Empty cart, or items no longer in stock"},
    502: {"model": ProblemDetail, "description": "The payment provider failed"},
    503: {"model": ProblemDetail, "description": "Payments are not configured"},
}


@router.get("/shipping-methods", summary="Shipping options and prices")
async def shipping_methods(service: CheckoutServiceDep) -> ShippingMethodList:
    return service.shipping_methods()


@router.post(
    "",
    summary="Reserve the cart's stock and start the payment",
    description=(
        "Creates a pending order from the signed-in user's cart, reserves its stock and returns "
        "what the browser needs to pay. Unpaid orders expire and release their stock. A previous "
        "unpaid order of the same user is cancelled first."
    ),
    responses=_CHECKOUT_ERRORS,
)
async def create_checkout(
    body: CheckoutRequest,
    user_id: CurrentUserDep,
    service: CheckoutServiceDep,
    idempotency_key: IdempotencyKey,
) -> CheckoutOut:
    return await service.create_checkout(user_id, body, idempotency_key)


@router.post(
    "/orders/{number}/simulate-payment",
    summary="Development only: pay for an order without a card (PAYMENTS_MODE=offline)",
    responses={
        404: {"model": ProblemDetail, "description": "Not in offline mode, or no such order"}
    },
)
async def simulate_payment(
    number: OrderNumber, user_id: CurrentUserDep, service: CheckoutServiceDep
) -> OrderOut:
    return await service.simulate_payment(user_id, number)
